	,collectibleActivated: function(collectible) {
		if(collectible.getType() == com_nick_pr_game_objects_CollectibleType.RED_COLLECTIBLE) this.redRangerButton.pickupAcquired(0.5); else if(collectible.getType() == com_nick_pr_game_objects_CollectibleType.BLUE_COLLECTIBLE) this.blueRangerButton.pickupAcquired(0.5); else if(collectible.getType() == com_nick_pr_game_objects_CollectibleType.GREEN_COLLECTIBLE) this.greenRangerButton.pickupAcquired(0.5); else if(collectible.getType() == com_nick_pr_game_objects_CollectibleType.BLACK_COLLECTIBLE) this.blackRangerButton.pickupAcquired(0.5); else if(collectible.getType() == com_nick_pr_game_objects_CollectibleType.PINK_COLLECTIBLE) {
			this.pinkRangerButton.pickupAcquired(0.5);
			if(!com_nick_pr_game_data_Data.getAchievements()[3].lock) {
				this.pinkCollectibleCount++;
				if(this.pinkCollectibleCount >= 5) com_nick_pr_game_data_Data.setAchievementProcess(3,1);
			}
		} else if(collectible.getType() == com_nick_pr_game_objects_CollectibleType.LIGHNING_COLLECTIBLE) this.dispatchEvent(new com_nick_pr_game_objects_GameHUDEvent(com_nick_pr_game_objects_GameHUDEvent.LIGHTNING_PICKUP_ACTIVATED)); else if(collectible.getType() == com_nick_pr_game_objects_CollectibleType.KENDALL_COLLECTIBLE) this.dispatchEvent(new com_nick_pr_game_objects_GameHUDEvent(com_nick_pr_game_objects_GameHUDEvent.KENDALL_PICKUP_ACTIVATED)); else if(collectible.getType() == com_nick_pr_game_objects_CollectibleType.KEEPER_COLLECTIBLE) this.dispatchEvent(new com_nick_pr_game_objects_GameHUDEvent(com_nick_pr_game_objects_GameHUDEvent.KEEPER_PICKUP_ACTIVATED)); else this.dispatchEvent(new com_nick_pr_game_objects_GameHUDEvent(com_nick_pr_game_objects_GameHUDEvent.ZOTAC_PICKUP_ACTIVATED));
	}
	,tutorialCollectibleActivated: function(collectible) {
		if(this.tutorialCount == 4) {
			this.tutorialResetButton();
			this.manageTutorial();
		} else if(this.tutorialCount == 9 && collectible.getType() == com_nick_pr_game_objects_CollectibleType.KENDALL_COLLECTIBLE) this.manageTutorial(); else if(this.tutorialCount == 10 && collectible.getType() == com_nick_pr_game_objects_CollectibleType.KEEPER_COLLECTIBLE) this.manageTutorial();
		this.collectibleActivated(collectible);
	}
	,getTutorialClickedButton: function() {
		return this.tutorialClickedButton;
	}
	,zotacActivated: function() {
		this.zotacEnabled = true;
		this.redRangerButton.animateZotak();
		this.blueRangerButton.animateZotak();
		this.greenRangerButton.animateZotak();
		this.blackRangerButton.animateZotak();
		this.pinkRangerButton.animateZotak();
		this.zotacSubtraction = 0;
		this.zotacTimer.reset();
		this.deactivate();
		this.addChild(this.overlay);
		if(indigo_lib_device_NickBrowserInfo.detectBrowser().touchDevice || indigo_lib_device_NickBrowserInfo.detectBrowser().isCocoonJS) this.addEventListener("touchEnd",$bind(this,this.onMouseUp)); else this.addEventListener(openfl_events_MouseEvent.MOUSE_UP,$bind(this,this.onMouseUp));
		this.numberOfClicks = 0;
	}
	,onMouseUp: function(e) {
		this.numberOfClicks++;
		this.animateClickedZotak();
		if(this.numberOfClicks >= this.numberOfClicksNeeded) {
			this.zotacDeactivated();
			this.activate(null);
		}
	}
	,zotacDeactivated: function() {
		if(this.zotacEnabled) {
			this.zotacEnabled = false;
			this.redRangerButton.animateZotakOut();
			this.blueRangerButton.animateZotakOut();
			this.greenRangerButton.animateZotakOut();
			this.blackRangerButton.animateZotakOut();
			this.pinkRangerButton.animateZotakOut();
			this.removeChild(this.overlay);
			this.collectibleMessageAnimateOut();
			if(indigo_lib_device_NickBrowserInfo.detectBrowser().touchDevice || indigo_lib_device_NickBrowserInfo.detectBrowser().isCocoonJS) this.removeEventListener("touchEnd",$bind(this,this.onMouseUp)); else this.removeEventListener(openfl_events_MouseEvent.MOUSE_UP,$bind(this,this.onMouseUp));
		}
	}
	,collectibleMessageAnimateIn: function(isKendall) {
		if(!this.tutorial) {
			this.gameMessage.set_alpha(0);
			this.gameMessage.set_visible(true);
			this.gameMessage.init(isKendall);
			this.gameMessage.set_x(indigo_jpmata_utils_display_DisplayUtility.getNominalWidth() * 0.49 - this.gameMessage.get_width() * 0.5);
			this.addChild(this.gameMessage);
			motion_Actuate.tween(this.gameMessage,0.5,{ alpha : 1}).onComplete($bind(this,this.collectibleMessageAnimateOutDelay));
			this.animateOutHardModeIndicator();
		}
	}
	,animateInHardModeIndicator: function() {
		if(com_nick_pr_game_data_Data.hardModeEnable()) {
			this.hardModeContainer.set_visible(true);
			this.hardModeTextfield.set_visible(true);
			motion_Actuate.tween(this.hardModeContainer,0.5,{ alpha : 1});
			motion_Actuate.tween(this.hardModeTextfield,0.5,{ alpha : 1});
		}
	}
	,animateOutHardModeIndicator: function() {
		if(com_nick_pr_game_data_Data.hardModeEnable()) {
			motion_Actuate.tween(this.hardModeContainer,0.5,{ alpha : 0});
			motion_Actuate.tween(this.hardModeTextfield,0.5,{ alpha : 0});
		}
	}
	,collectibleMessageZotacAnimateIn: function() {
		this.gameMessage.set_alpha(0);
		this.gameMessage.set_visible(true);
		this.gameMessage.initZotac();
		this.addChild(this.gameMessage);
		motion_Actuate.stop(this.gameMessage,null,false,false);
		motion_Actuate.tween(this.gameMessage,0.5,{ alpha : 1});
		this.animateOutHardModeIndicator();
	}
	,collectibleMessageAnimateOutDelay2: function() {
		this.timerFunction = motion_Actuate.timer(3).onComplete($bind(this,this.collectibleMessageAnimateOut));
	}
	,collectibleMessageAnimateOutDelay: function() {
		this.timerFunction = motion_Actuate.timer(2).onComplete($bind(this,this.collectibleMessageAnimateOut));
	}
	,collectibleMessageAnimateOut: function() {
		this.timerFunction = null;
		motion_Actuate.tween(this.gameMessage,1,{ alpha : 0}).onComplete($bind(this,this.removeCollectibleMessage));
		this.animateInHardModeIndicator();
	}
	,removeCollectibleMessage: function() {
		this.removeChild(this.gameMessage);
	}
