	,deactivate: function() {
		if(this.isEnabled) {
			this.isEnabled = false;
			if(!this.bossBattle) {
				this.redRangerButton.deactivate();
				this.blueRangerButton.deactivate();
				this.greenRangerButton.deactivate();
				this.blackRangerButton.deactivate();
				this.pinkRangerButton.deactivate();
			} else {
				this.triceraButton.deactivate();
				this.flamethrowerButton.deactivate();
				this.steegoPunchButton.deactivate();
			}
			this.lightningBoltButton.deactivate();
		}
	}
