	,update: function() {
		if(!this.tutorial) {
			this.redRangerButton.update();
			this.blueRangerButton.update();
			this.greenRangerButton.update();
			this.blackRangerButton.update();
			this.pinkRangerButton.update();
			this.megaZordButton.updateMegazord();
			this.flamethrowerButton.update();
			this.triceraButton.update();
			this.steegoPunchButton.update();
			if(this.zotacEnabled) {
				if(this.zotacTimer.getTimeInMilliseconds() >= this.zotacSubtraction) {
					this.zotacSubtraction += 1000;
					this.dispatchEvent(new com_nick_pr_game_objects_GameHUDEvent(com_nick_pr_game_objects_GameHUDEvent.ZOTAC_REMOVE_ONE_ATTACK));
				}
				if(this.zotacTimer.getTimeInMilliseconds() >= this.zotacDuration) {
					this.zotacDeactivated();
					this.activate(null);
				}
			}
		} else if(this.tutorialCount >= 2) {
			this.redRangerButton.update();
			this.blueRangerButton.update();
			this.greenRangerButton.update();
			this.blackRangerButton.update();
			this.pinkRangerButton.update();
		}
	}
