	,positionGiantCharacter: function() {
		indigo_jpmata_managers_SoundManager.instance().playSFX("game/vo/megazord_transform.mp3");
		this.changeBackground(true);
		this.removeRangersOnScreen();
		this.enemyManager.getGiantBoss().setCharacterPosition(this.battleStadium.getRightGiantBossPosition());
		this.enemyManager.getGiantBoss().resetPosition();
		this.rangerManager.getMegazord().setCharacterPosition(this.battleStadium.getLeftGiantBossPosition());
		this.rangerManager.getMegazord().resetPosition();
		this.rangerManager.getMegazord().startCharacter();
		this.gameCanvas.addChild(this.rangerManager.getMegazord());
		this.depthSwap.addObject(this.rangerManager.getMegazord());
		this.hud.activateMegazordButtons();
		this.stateManager(com_nick_pr_screens_GameState.BOSS_FIGHT);
		this.turnBaseManager.reset();
		this.rangerManager.getMegazord().addEventListener(com_nick_pr_game_objects_character_CharacterEvent.NORMALATTACKCOOLDOWNCOMPLETE,($_=this.turnBaseManager,$bind($_,$_.addToQueue)));
		this.enemyManager.getGiantBoss().addEventListener(com_nick_pr_game_objects_character_CharacterEvent.NORMALATTACKCOOLDOWNCOMPLETE,($_=this.turnBaseManager,$bind($_,$_.addToQueue)));
		this.rangerManager.getMegazord().reset();
		this.enemyManager.getGiantBoss().reset();
		this.turnBaseManager.enable();
	}
	,removeRangersOnScreen: function() {
		var _g = 0;
		var _g1 = this.rangerManager.getRangers();
		while(_g < _g1.length) {
			var ranger = _g1[_g];
			++_g;
			this.gameCanvas.removeChild(ranger);
			this.depthSwap.removeObject(ranger);
			ranger.stopCharacter();
		}
	}
	,respawnRangers: function() {
		this.addRangersOnScreen();
		this.removeMegaZord();
		this.hud.deactivateMegazordButtons();
		this.changeBackground(false);
		this.rangerManager.animateReturnToBattle();
	}
